import math


def _number(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError("expected a number")
    value = float(value)
    if not math.isfinite(value):
        raise ValueError("number must be finite")
    return value


def _vector(value):
    if isinstance(value, (str, bytes)):
        raise TypeError("vector must be an iterable")
    try:
        values = list(value)
    except TypeError:
        raise TypeError("vector must be an iterable") from None
    if len(values) != 3:
        raise ValueError("vector must contain three values")
    return [_number(item) for item in values]


def project_state(bodies, anchor=None):
    if isinstance(bodies, (str, bytes)):
        raise TypeError("bodies must be an iterable")
    try:
        source = list(bodies)
    except TypeError:
        raise TypeError("bodies must be an iterable") from None
    result = []
    names = set()
    for body in source:
        if not isinstance(body, dict):
            raise TypeError("each body must be a dictionary")
        if set(body) != {"name", "mass", "position", "velocity"}:
            raise ValueError("invalid body fields")
        name = body["name"]
        if not isinstance(name, str):
            raise TypeError("name must be a string")
        if not name or name in names:
            raise ValueError("names must be non-empty and unique")
        names.add(name)
        mass = _number(body["mass"])
        if mass <= 0:
            raise ValueError("mass must be positive")
        position = _vector(body["position"])
        velocity = _vector(body["velocity"])
        position[2] = 0.0
        velocity[2] = 0.0
        result.append({"name": name, "mass": mass, "position": position, "velocity": velocity})
    if not result:
        if anchor is not None:
            raise ValueError("unknown anchor")
        return []
    if anchor is not None and not isinstance(anchor, str):
        raise TypeError("anchor must be a string or None")
    target = 0 if anchor is None else next((i for i, b in enumerate(result) if b["name"] == anchor), -1)
    if target < 0:
        raise ValueError("unknown anchor")
    px = sum(b["mass"] * b["velocity"][0] for b in result)
    py = sum(b["mass"] * b["velocity"][1] for b in result)
    result[target]["velocity"][0] = -px / result[target]["mass"]
    result[target]["velocity"][1] = -py / result[target]["mass"]
    return result

